import{_ as i,f as a,c as e,a6 as t}from"./chunks/framework.CJQKpl5I.js";const p=JSON.parse('{"title":"第 3 章 国产软件技术基础","description":"","frontmatter":{},"headers":[],"relativePath":"ch03_software.md","filePath":"ch03_software.md"}'),r={name:"ch03_software.md"};function o(h,l,d,u,n,s){return a(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="第-3-章-国产软件技术基础" tabindex="-1">第 3 章 国产软件技术基础 <a class="header-anchor" href="#第-3-章-国产软件技术基础" aria-label="Permalink to &quot;第 3 章 国产软件技术基础&quot;">​</a></h1><p>考核占比 20%。重点考察国产基础软件的基本概念、功能分类及通用工作原理。</p><h2 id="_3-1-数据库基础" tabindex="-1">3.1 数据库基础 <a class="header-anchor" href="#_3-1-数据库基础" aria-label="Permalink to &quot;3.1 数据库基础&quot;">​</a></h2><h3 id="关系数据库" tabindex="-1">关系数据库 <a class="header-anchor" href="#关系数据库" aria-label="Permalink to &quot;关系数据库&quot;">​</a></h3><p>关系数据库用表组织数据，表由行和列构成。</p><ul><li>主键唯一标识表中的记录</li><li>外键等关联字段用于建立表之间的关系</li><li>订单表通过 customer_id 关联客户表，体现表与表之间的关联关系</li><li>DBMS 提供数据定义、查询、事务等管理能力</li><li>基本 SQL 操作：SELECT 查询、INSERT 插入、UPDATE 更新、DELETE 删除</li></ul><h3 id="事务与-acid" tabindex="-1">事务与 ACID <a class="header-anchor" href="#事务与-acid" aria-label="Permalink to &quot;事务与 ACID&quot;">​</a></h3><p>事务是一组不可分割的操作序列。</p><ul><li>原子性要求事务中的操作要么全部成功，要么作为整体失败</li><li>一致性保证事务执行前后数据都处于合法状态</li><li>隔离性保证并发事务互不干扰</li><li>持久性保证提交后数据不会丢失</li><li>事务隔离级别包括读未提交、读已提交、可重复读、串行化，隔离级别越高并发性能越低</li></ul><h3 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h3><ul><li>索引提升特定查询的速度</li><li>索引需要额外存储空间</li><li>索引会增加写入和维护的成本</li><li>建立索引只会加快读取而增加写入维护成本</li></ul><h3 id="nosql-数据库" tabindex="-1">NoSQL 数据库 <a class="header-anchor" href="#nosql-数据库" aria-label="Permalink to &quot;NoSQL 数据库&quot;">​</a></h3><p>NoSQL 按数据模型分为多种类型：</p><table tabindex="0"><thead><tr><th>类型</th><th>数据组织</th><th>适合场景</th></tr></thead><tbody><tr><td>键值</td><td>键值对</td><td>按唯一键快速读写简单状态</td></tr><tr><td>文档</td><td>JSON 文档</td><td>灵活结构、嵌套数据</td></tr><tr><td>宽列族</td><td>列族组织</td><td>海量稀疏数据</td></tr><tr><td>图</td><td>节点与边</td><td>关系网络查询</td></tr></tbody></table><ul><li>键值模型适合按唯一键快速读写大量简单状态，例如会话状态</li><li>宽列模型适合海量稀疏、按列族组织的数据</li><li>NoSQL 按数据模型分类，与存储介质无关</li></ul><h3 id="数据库迁移" tabindex="-1">数据库迁移 <a class="header-anchor" href="#数据库迁移" aria-label="Permalink to &quot;数据库迁移&quot;">​</a></h3><ul><li>数据库迁移不能只比较数据条数</li><li>需要检查结构、SQL 兼容、数据一致性和关键业务功能</li><li>必要时评估性能与高可用方案</li></ul><h2 id="_3-2-中间件" tabindex="-1">3.2 中间件 <a class="header-anchor" href="#_3-2-中间件" aria-label="Permalink to &quot;3.2 中间件&quot;">​</a></h2><h3 id="中间件的定位与能力" tabindex="-1">中间件的定位与能力 <a class="header-anchor" href="#中间件的定位与能力" aria-label="Permalink to &quot;中间件的定位与能力&quot;">​</a></h3><p>中间件位于操作系统基础能力与业务应用之间，为分布式应用提供通用能力。</p><ul><li>通用能力包括事务协调、通信、消息传递、服务治理</li><li>中间件减少应用重复实现，促进系统集成</li><li>企业把认证、消息事务等通用能力集中到中间件层，避免每个应用各自实现</li></ul><h3 id="消息队列" tabindex="-1">消息队列 <a class="header-anchor" href="#消息队列" aria-label="Permalink to &quot;消息队列&quot;">​</a></h3><p>消息队列通过生产者、队列或主题、消费者实现异步与解耦。</p><ul><li>生产者发送消息，消费者按自身能力处理</li><li>高峰期请求短时间激增时，消息队列先承接再按消费者能力处理，实现削峰缓冲</li><li>异步处理让生产和消费解耦，不互相阻塞</li></ul><p>消息可靠处理需要以下机制配合：</p><ul><li>确认机制，消费者处理成功后才确认，避免失败被当作成功</li><li>失败重试，处理失败的消息重新投递</li><li>幂等处理，重复消费同一消息不会产生重复业务</li><li>死信或异常消息处理，超过重试次数的消息转入专门队列</li></ul><h3 id="常见中间件" tabindex="-1">常见中间件 <a class="header-anchor" href="#常见中间件" aria-label="Permalink to &quot;常见中间件&quot;">​</a></h3><ul><li>消息中间件：Kafka 面向高吞吐日志和流处理，RabbitMQ 面向灵活路由和低延迟</li><li>缓存中间件：Redis 内存键值存储，用于缓存和会话</li><li>分布式协调：ZooKeeper 等提供配置与协调能力</li></ul><h2 id="_3-3-兼容与迁移验证" tabindex="-1">3.3 兼容与迁移验证 <a class="header-anchor" href="#_3-3-兼容与迁移验证" aria-label="Permalink to &quot;3.3 兼容与迁移验证&quot;">​</a></h2><h3 id="业务栈兼容验证" tabindex="-1">业务栈兼容验证 <a class="header-anchor" href="#业务栈兼容验证" aria-label="Permalink to &quot;业务栈兼容验证&quot;">​</a></h3><ul><li>完整业务栈包括操作系统、数据库、中间件和应用</li><li>兼容验证应针对实际组合后的完整技术栈和相关业务路径</li><li>只验证某个单品能否启动不足以证明整套系统兼容</li><li>应用能启动并不能认定各组件之间不存在兼容性问题</li></ul><h3 id="应用迁移流程" tabindex="-1">应用迁移流程 <a class="header-anchor" href="#应用迁移流程" aria-label="Permalink to &quot;应用迁移流程&quot;">​</a></h3><ol><li>盘点应用清单与依赖，识别迁移范围、依赖和潜在问题</li><li>完成目标架构搭建</li><li>功能验证</li><li>兼容性验证</li><li>回归测试</li></ol><ul><li>回归测试用于确认迁移没有破坏既有相关功能</li><li>新系统上线前执行回归测试是标准环节</li><li>跨架构迁移涉及编译、运行库和驱动等层面的兼容性检查</li></ul><h3 id="分布式系统概念" tabindex="-1">分布式系统概念 <a class="header-anchor" href="#分布式系统概念" aria-label="Permalink to &quot;分布式系统概念&quot;">​</a></h3><ul><li>CAP 定理表明分布式系统在一致性、可用性、分区容错性之间需要取舍</li><li>分区容错性在分布式系统中必须满足</li><li>单点故障风险通过冗余和集群方案降低</li><li>容器化用 Docker 等工具打包应用与环境，实现环境一致性</li></ul><h2 id="_3-4-国产基础软件生态" tabindex="-1">3.4 国产基础软件生态 <a class="header-anchor" href="#_3-4-国产基础软件生态" aria-label="Permalink to &quot;3.4 国产基础软件生态&quot;">​</a></h2><p>信创环境下国产软件覆盖基础软件各层：</p><ul><li><p>国产数据库：达梦数据库、人大金仓、GaussDB、openGauss、OceanBase</p></li><li><p>国产中间件：东方通中间件、金蝶天燕、宝兰德</p></li><li><p>国产办公软件：金山 WPS、永中 Office</p></li><li><p>国产操作系统：统信 UOS、麒麟系统</p></li><li><p>国产浏览器：360 安全浏览器等基于 Chromium 内核的国产浏览器</p></li><li><p>国产软件与 X86、ARM 等多种架构适配</p></li><li><p>国产数据库大多兼容主流 SQL 标准，支持事务和索引等基础能力</p></li><li><p>中间件提供消息、事务、服务治理等通用能力，应用通过标准接口接入</p></li><li><p>信创环境强调软硬件全栈自主可控，从芯片、操作系统到应用软件形成完整生态</p></li></ul><h2 id="_3-5-虚拟化与容器" tabindex="-1">3.5 虚拟化与容器 <a class="header-anchor" href="#_3-5-虚拟化与容器" aria-label="Permalink to &quot;3.5 虚拟化与容器&quot;">​</a></h2><h3 id="虚拟机与容器" tabindex="-1">虚拟机与容器 <a class="header-anchor" href="#虚拟机与容器" aria-label="Permalink to &quot;虚拟机与容器&quot;">​</a></h3><ul><li>虚拟机通过 Hypervisor 模拟完整硬件，每个虚拟机包含独立操作系统，隔离性强、开销大</li><li>容器共享宿主机内核，只打包应用及依赖，启动快、资源占用小</li><li>容器适合微服务和批量部署，虚拟机适合强隔离场景</li><li>Docker 是主流容器工具，镜像包含应用和运行环境，镜像构建后可在任意 Docker 环境运行</li></ul><h3 id="容器基础命令" tabindex="-1">容器基础命令 <a class="header-anchor" href="#容器基础命令" aria-label="Permalink to &quot;容器基础命令&quot;">​</a></h3><ul><li>docker pull 拉取镜像，docker run 运行容器，docker ps 查看运行中容器</li><li>docker build 从 Dockerfile 构建镜像</li><li>docker stop 停止容器，docker rm 删除容器</li><li>容器网络和存储卷提供对外访问与数据持久化</li></ul><h2 id="_3-6-数据文件与-json" tabindex="-1">3.6 数据文件与 JSON <a class="header-anchor" href="#_3-6-数据文件与-json" aria-label="Permalink to &quot;3.6 数据文件与 JSON&quot;">​</a></h2><ul><li>JSON 是轻量级数据交换格式，以键值对和嵌套结构组织数据</li><li>JSON 适合保存结构化数据，例如学生信息、配置项</li><li>程序启动时从数据文件加载数据，写入时保存到文件，实现持久化</li><li>数据持久化保证程序重启后数据不丢失</li><li>数据处理流程：读取文件、解析、更新、写回文件</li><li>统计类结果从数据实时计算得出，写死在程序中的固定结果无法反映数据变化</li></ul><h3 id="容器与智能体环境" tabindex="-1">容器与智能体环境 <a class="header-anchor" href="#容器与智能体环境" aria-label="Permalink to &quot;容器与智能体环境&quot;">​</a></h3><ul><li>智能体运行环境可用容器打包，保证依赖一致</li><li>模型推理服务常以容器方式部署，便于迁移和扩缩容</li><li>容器环境与宿主机隔离，访问宿主机资源需要显式挂载和权限配置</li></ul>',48)])])}const b=i(r,[["render",o]]);export{p as __pageData,b as default};
